    bronze_sandsieveshaker = { name = "Bronast tresoča sitana za pesek", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast tresoča sitana za pesek za livarje." },
