SandSieveShakerMaker.ironStock=16; SandSieveShakerMaker.bronzeStock=12; SandSieveShakerMaker.woodStock=14; SandSieveShakerMaker.leatherStock=8; SandSieveShakerMaker.silverStock=8; SandSieveShakerMaker.goldStock=6; SandSieveShakerMaker.jewelStock=4; SandSieveShakerMaker.pearlStock=4
SandSieveShakerMaker.productStock = {}; SandSieveShakerMaker.buildings = {}; SandSieveShakerMaker.maker = nil; SandSieveShakerMaker.activeMaking = {}; SandSieveShakerMaker.totalProducts = 0; SandSieveShakerMaker.dayTimer = 0
function SandSieveShakerMaker.init() SandSieveShakerMaker.ironStock=16; SandSieveShakerMaker.bronzeStock=12; SandSieveShakerMaker.woodStock=14; SandSieveShakerMaker.leatherStock=8; SandSieveShakerMaker.silverStock=8; SandSieveShakerMaker.goldStock=6; SandSieveShakerMaker.jewelStock=4; SandSieveShakerMaker.pearlStock=4; SandSieveShakerMaker.productStock={}; SandSieveShakerMaker.buildings={}; SandSieveShakerMaker.maker=nil; SandSieveShakerMaker.activeMaking={}; SandSieveShakerMaker.totalProducts=0; SandSieveShakerMaker.dayTimer=0; print("[SandSieveShakerMaker] Royal Sand Sieve Shaker Maker System initialized (6 products, 4 buildings)") end
function SandSieveShakerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SandSieveShakerMaker.maker={name=n or ("Treskar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Treskar najet: %s (spretnost: %d)",SandSieveShakerMaker.maker.name,s),"success") end; return true end
function SandSieveShakerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SandSieveShakerMaker.build(id) local ok,e=SandSieveShakerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SandSieveShakerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SandSieveShakerMaker.getQualityBonus() local b=0; for _,bd in ipairs(SandSieveShakerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SandSieveShakerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SandSieveShakerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SandSieveShakerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SandSieveShakerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SandSieveShakerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SandSieveShakerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SandSieveShakerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SandSieveShakerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SandSieveShakerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SandSieveShakerMaker.buildings==0 then return false,"Potrebna treskalna delavnica" end; if not SandSieveShakerMaker.maker then return false,"Potreben treskar" end; return true end
function SandSieveShakerMaker.make(pt,qty) qty=qty or 1; local ok,e=SandSieveShakerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SandSieveShakerMaker.ironStock=SandSieveShakerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SandSieveShakerMaker.bronzeStock=SandSieveShakerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SandSieveShakerMaker.woodStock=SandSieveShakerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SandSieveShakerMaker.leatherStock=SandSieveShakerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SandSieveShakerMaker.silverStock=SandSieveShakerMaker.silverStock-d.silverCost*qty end; if d.goldCost then SandSieveShakerMaker.goldStock=SandSieveShakerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SandSieveShakerMaker.jewelStock=SandSieveShakerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SandSieveShakerMaker.pearlStock=SandSieveShakerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SandSieveShakerMaker.maker then t=math.max(1,t-math.floor(SandSieveShakerMaker.maker.skill/13)) end; table.insert(SandSieveShakerMaker.activeMaking,{id="sandsieveshaker_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SandSieveShakerMaker.completeMaking(m) local q=1.0+(SandSieveShakerMaker.getQualityBonus()/100); if SandSieveShakerMaker.maker then q=q+(SandSieveShakerMaker.maker.skill/140) end; q=math.min(2.5,q); SandSieveShakerMaker.productStock[m.productType]=(SandSieveShakerMaker.productStock[m.productType] or 0)+m.quantity; SandSieveShakerMaker.totalProducts=SandSieveShakerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SandSieveShakerMaker.maker then SandSieveShakerMaker.maker.itemsMade=SandSieveShakerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SandSieveShakerMaker.maker.skill=math.min(100,SandSieveShakerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Treskač izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sandsieveshaker.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SandSieveShakerMaker.update(dt) if not _G.state then return end; SandSieveShakerMaker.dayTimer=SandSieveShakerMaker.dayTimer+dt; if SandSieveShakerMaker.dayTimer>=30 then SandSieveShakerMaker.dayTimer=0; for i=#SandSieveShakerMaker.activeMaking,1,-1 do local m=SandSieveShakerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SandSieveShakerMaker.completeMaking(m); table.remove(SandSieveShakerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SandSieveShakerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SandSieveShakerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SandSieveShakerMaker.getStats() return {ironStock=SandSieveShakerMaker.ironStock,bronzeStock=SandSieveShakerMaker.bronzeStock,woodStock=SandSieveShakerMaker.woodStock,leatherStock=SandSieveShakerMaker.leatherStock,silverStock=SandSieveShakerMaker.silverStock,goldStock=SandSieveShakerMaker.goldStock,jewelStock=SandSieveShakerMaker.jewelStock,pearlStock=SandSieveShakerMaker.pearlStock,productStock=SandSieveShakerMaker.productStock,numBuildings=#SandSieveShakerMaker.buildings,hasMaker=SandSieveShakerMaker.maker~=nil,makerName=SandSieveShakerMaker.maker and SandSieveShakerMaker.maker.name or "—",makerSkill=SandSieveShakerMaker.maker and SandSieveShakerMaker.maker.skill or 0,activeMaking=#SandSieveShakerMaker.activeMaking,totalProducts=SandSieveShakerMaker.totalProducts} end
return SandSieveShakerMaker
